/**
 * Story 426: the Local AI switch. `timed` holds the chat server for a fixed window, `kept` until it
 * is turned off; `until` is when a `timed` hold ends (a stored-timestamp instant), else null.
 */
export const LOCAL_AI_MODES = ['off', 'timed', 'kept'] as const;
export type LocalAiMode = typeof LOCAL_AI_MODES[number];

/**
 * Story 427: the chat server's two sets of start flags. `app` is the vision setup the app's own
 * features run on (32k); `text` drops the vision projector for a larger context, entirely in VRAM,
 * and is only offered in server mode.
 */
export const LOCAL_AI_SETUPS = ['app', 'text'] as const;
export type LocalAiSetup = typeof LOCAL_AI_SETUPS[number];

export interface LocalAiState {
    mode: LocalAiMode;
    until: string | null;
    /** The setup Local AI holds; null while it is off. */
    setup: LocalAiSetup | null;
    /** Why the text-only setup can't be chosen now (GUI mode, or the sidecar's raw error); null when it can. */
    text_unavailable: string | null;
}

export interface LocalAiRequest {
    mode: LocalAiMode;
    /** Ignored when `mode` is off; `app` when left out. */
    setup?: LocalAiSetup;
}
